#[test]
fn mixedmath_language_instantiates() {
    let lang = MixedMathLanguage;
    assert_eq!(lang.name(), "MixedMath");
}

#[test]
fn mixedmath_metadata_populated() {
    let lang = MixedMathLanguage;
    let meta = lang.metadata();
    assert!(!meta.types().is_empty(), "language should have at least one type");
    assert!(!meta.terms().is_empty(), "language should have at least one term");
}

#[test]
fn unit_mixedmath_bool_and() {
    mettail_runtime::clear_var_cache();
    let term = Bool::And(Box::new(Bool::BoolLit(false)), Box::new(Bool::BoolLit(false)));
    let displayed = format!("{}", term);
    assert!(!displayed.is_empty(), "Display should produce non-empty output for And");
    if let Ok(parsed) = Bool::parse(&displayed) {
        let re_displayed = format!("{}", parsed);
        assert_eq!(displayed, re_displayed,
            "Roundtrip failed for And: {} != {}", displayed, re_displayed);
    }
}

